ow.addColorStop(0,nd.color.replace(')',',0.45)').replace('rgb','rgba'));glow.addColorStop(1,'rgba(0,0,0,0)');}ctx.fillStyle=glow;ctx.beginPath();ctx.arc(nd.x,nd.y,ts*1.7,0,Math.PI*2);ctx.fill();const bg=ctx.createRadialGradient(nd.x-ts*0.25,nd.y-ts*0.25,ts*0.08,nd.x,nd.y,ts);bg.addColorStop(0,'#ffffff');bg.addColorStop(0.3,nd.color);bg.addColorStop(1,'#000000');ctx.fillStyle=bg;ctx.beginPath();ctx.arc(nd.x,nd.y,ts,0,Math.PI*2);ctx.fill();ctx.strokeStyle=inPaths?'#ffd700':'rgba(255,255,255,0.25)';ctx.lineWidth=inPaths?1.8:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=`${Math.max(7,ts*0.5)}px 'Courier New'`;ctx.textAlign='center';ctx.fillText(nd.id,nd.x,nd.y+ts+10);}for(let p=0;p<this.highlightedPaths.length;p++){const path=this.highlightedPaths[p];if(path.length<2)continue;const t=(this.animPhase+p*0.3)%1;const idx=Math.floor(t*(path.length-1));const nxt=Math.min(idx+1,path.length-1);const from=this.nodes[path[idx]],to=this.nodes[path[nxt]];if(from&&to){const fr=(t*(path.length-1))%1;const px=from.x+(to.x-from.x)*fr,py=from.y+(to.y-from.y)*fr;const color=this.pathColors[p%this.pathColors.length];ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(px,py,4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}}}
