        async function smartFetch(url, options = {}, isCorsSafe = false) {
            // Try direct first
            if (isCorsSafe || State.proxyMode === 'direct') {
                try {
                    const controller = new AbortController();
                    const timeout = setTimeout(() => controller.abort(), 12000);
                    const r = await fetch(url, { ...options, signal: controller.signal });
                    clearTimeout(timeout);
                    if (r.ok) return r;
                    if (r.status >= 400) throw new Error('HTTP ' + r.status);
                } catch (e) {
                    if (State.proxyMode === 'direct') {
                        // Fall through to try built-in proxy as emergency fallback
                    } else { throw e; }
                }
            }
            // Try proxy
            const proxy = getEffectiveProxyUrl() || BUILTIN_PROXIES[0];
            try {
                const controller = new AbortController();
                const timeout = setTimeout(() => controller.abort(), 15000);
                const r = await fetch(proxy + encodeURIComponent(url), { ...options, signal: controller.signal });
                clearTimeout(timeout);
                if (!r.ok) throw new Error('Proxy HTTP ' + r.status);
                const text = await r.text();
                if (text.startsWith('<') || text.includes('corsdemo')) throw new Error('Non-JSON proxy response');
                try {
                    return new Response(JSON.stringify(JSON.parse(text)), { status: 200, headers: { 'Content-Type':
                            'application/json' } });
                } catch {
                    return new Response(text, { status: 200, headers: { 'Content-Type': 'text/plain' } });
                }
            } catch (e) {
                rotateProxy();
                // Try one more proxy
                try {
                    const proxy2 = getEffectiveProxyUrl() || BUILTIN_PROXIES[currentProxyIndex];
                    const r2 = await fetch(proxy2 + encodeURIComponent(url), options);
                    if (!r2.ok) throw new Error('Proxy2 HTTP ' + r2.status);
                    const text2 = await r2.text();
                    try { return new Response(JSON.stringify(JSON.parse(text2)), { status: 200, headers: { 'Content-Type':
                                'application/json' } }); } catch { return new Response(text2, { status: 200,
                            headers: { 'Content-Type': 'text/plain' } }); }
                } catch (e2) { throw new Error('All fetch attempts exhausted: ' + e2.message); }
            }
        }
