        function bellmanFord(start, depth = 5) { const cs = Object.keys(State.graph); if (!cs.includes(start)) return []; const
                mode = document.getElementById('arbMode').value; const dist = {},
                pred = {};
            cs.forEach(c => { dist[c] = Infinity;
                pred[c] = null; });
            dist[start] = 0; for (let i = 0; i < Math.min(depth - 1, cs.length - 1); i++) { let upd = false; for (const u of
                    cs) { const nb = State.graph[u]; if (!nb) continue; for (const v in nb) { const w = nb[v].weight; if (
                        dist[u] !== Infinity && dist[u] + w < dist[v]) { if (mode === 'intra' && !State
                            .selectedIntraExchanges.has(nb[v].exchange)) continue;
                    dist[v] = dist[u] + w;
                    pred[v] = u;
                    upd = true; } } } if (!upd) break; } const opps = []; const target = State.getTargetAssets(); for (
                const u of cs) { const nb = State.graph[u]; if (!nb) continue; for (const v in nb) { if (dist[u] !==
                    Infinity && dist[u] + nb[v].weight < dist[v]) { const cyc = (() => { const c = [v]; let cur =
                        v; const vis = new Set();
                    vis.add(v); for (let i = 0; i < depth; i++) { cur = pred[cur]; if (!cur) return null;
                        c.push(cur); if (cur === start) return c; if (vis.has(cur)) return null;
                        vis.add(cur); } return null; })(); if (cyc && cyc[0] === start && target.includes(
                        start)) { let amt = 1000; const edges = []; let tl = Infinity; for (let i = 0; i <
                            cyc.length - 1; i++) { const e = State.graph[cyc[i]]?.[cyc[i + 1]]; if (!e)
                            break;
                        amt *= e.rate;
