                this.conflictEdges = conflictEdges || new Set(); const seen = new Set();
                this.maxPower = Math.max(1, ...Object.values(this.purchasePower)); for (const [b, tgts] of Object.entries(
                        graph)) { if (!this.nodes[b]) this.nodes[b] = { id: b, x: 0, y: 0, power: this.purchasePower[b] ||
                            0, color: this.getColor(b), oppCount: 0 }; for (const [t, e] of Object.entries(tgts)) { const
                            k = [b, t].sort().join('|'); if (!seen.has(k)) { seen.add(k);
                        this.edges.push({ from: b, to: t, vol: e.volume || 0, liq: e.liquidity || 0, rate: e
                            .rate }); } if (!this.nodes[t]) this.nodes[t] = { id: t, x: 0, y: 0, power: this
                            .purchasePower[t] || 0, color: this.getColor(t), oppCount: 0 }; } } if (opps) { for (
                        const o of [...(opps.mega || []), ...(opps.triangular || []), ...(opps.bellman || [])]) { for (
                            const n of o.path) { if (this.nodes[n]) this.nodes[n].oppCount++; } } }
                this.forceLayout();
                this.startAnim(); }
            getColor(id) { const c = ['#ffd700', '#00f0ff', '#ff00ff', '#00ffaa', '#ff8888', '#88ff88', '#ffaa00',
                '#aa88ff', '#ff4488', '#44ff88']; let h = 0; for (let i = 0; i < id.length; i++) h = ((h << 5) -
                    h) + id.charCodeAt(i); return c[Math.abs(h) % c.length]; }
