                    .width / 2,
                    cy = this.canvas.height / 2; const rad = Math.min(cx, cy) * 0.65;
                nl.forEach((nd, i) => { const a = (2 * Math.PI * i) / n - Math.PI / 2;
                    nd.x = cx + rad * Math.cos(a);
                    nd.y = cy + rad * Math.sin(a); }); const iters = Math.min(35, Math.max(12, n)); for (let iter = 0; iter <
                    iters; iter++) { for (let i = 0; i < n; i++) { for (let j = i + 1; j < n; j++) { const dx = nl[i].x -
                            nl[j].x,
                            dy = nl[i].y - nl[j].y; const d = Math.max(1, Math.sqrt(dx * dx + dy * dy)); const f =
                            700 / (d * d); const fx = (dx / d) * f,
                            fy = (dy / d) * f;
