                        .maxPower); const sz = 7 + pr * 16; const ob = Math.min(7, (nd.oppCount || 0) * 1.8); const ts =
                        sz + ob; const glow = ctx.createRadialGradient(nd.x, nd.y, 0, nd.x, nd.y, ts * 1.7); if (inPaths) {
