                ctx.fillText(nd.id, nd.x, nd.y + ts + 10); } for (let p = 0; p < this.highlightedPaths.length; p++) { const
                        path = this.highlightedPaths[p]; if (path.length < 2) continue; const t = (this.animPhase + p * 0
