                const bundle = await mod.selectBundle(JSDELIVR_BUNDLES);
                const worker = new Worker(bundle.mainWorker);
                const logger = new mod.ConsoleLogger();
                const db = new mod.AsyncDuckDB(logger, worker);
                await db.instantiate(bundle.mainModule);
                const conn = await db.connect();
                State.db = db;
                State.conn = conn;
                await conn.query(
                    `CREATE TABLE IF NOT EXISTS ohlc (timestamp BIGINT, base VARCHAR, target VARCHAR, open DOUBLE, high DOUBLE, low DOUBLE, close DOUBLE, volume DOUBLE)`
                    );
                document.getElementById('dbStatus').innerHTML = '✅ DuckDB-Wasm ready';
                log('🦆 DuckDB-Wasm ready', 'success');
            } catch (e) { document.getElementById('dbStatus').innerHTML = '⚠️ DuckDB unavailable';
                log('🦆 DuckDB not available: ' + e.message, 'warning'); }
