        async function importTorrentFile(file) { if (!State.conn) { log('DuckDB not ready for import',
            'warning'); return; }
            file.getBuffer(async (err, buf) => { if (err) { log('Torrent read error: ' + err,
            'error'); return; } if (file.name.endsWith('.csv')) { const text = new TextDecoder().decode(
                    buf); const lines = text.split('\n'); if (lines.length < 2) return; let count = 0; for (let i =
                    1; i < Math.min(lines.length, 10000); i++) { const cols = lines[i].split(','); if (cols
                    .length >= 7) { try { await State.conn.query(
                            `INSERT INTO ohlc VALUES (?,?,?,?,?,?,?,?)`, [parseInt(cols[0]) || Date
                                .now(), cols[1]?.trim(), cols[2]?.trim(), parseFloat(cols[3]) || 0,
                                parseFloat(cols[4]) || 0, parseFloat(cols[5]) || 0, parseFloat(cols[
                                    6]) || 0, parseFloat(cols[7]) || 0
                            ]);
                        count++; } catch (e) {} } }
                log(`📊 Imported ${count} rows into DuckDB`, 'success'); } else if (file.name.endsWith('.parquet')) { try {
                        const u8 = new Uint8Array(buf); await State.db.registerFileBuffer(file.name, u8); await State
                        .conn.query(
                            `CREATE OR REPLACE TABLE ohlc AS SELECT * FROM read_parquet('${file.name}')`);
                    log('📊 Parquet file loaded into DuckDB', 'success'); } catch (e) { log('Parquet import error: ' +
                        e.message, 'error'); } } }); }
