        function placeDEXOrder(side = 'buy') { const coin = document.getElementById('dexCoin').value.trim().toUpperCase(); const
                amount = parseFloat(document.getElementById('dexAmount').value); if (!coin || !amount || amount <= 0)
            return; if (!window.yDexOrders) { log('DEX not initialized', 'warning'); return; }
